List<Integer> nums = new ArrayList<>(List.of(1, 2, 3, 4));
for (Integer n : nums) {
    if (n % 2 == 0) {
        nums.remove(n);
    }
}
System.out.println(nums);

example.content:
Iterator<Integer> it = nums.iterator();
while (it.hasNext()) {
    if (it.next() % 2 == 0) it.remove();
}
// or simply: nums.removeIf(n -> n % 2 == 0);   ->  [1, 3]

